<script setup lang="ts">
import { ArrowUpRight, Check, ChevronDown, Cloud, KeyRound, LoaderCircle, LogOut, Mail, Settings2, ShieldCheck, UserRound, X } from 'lucide-vue-next'
const {user,refresh,logout}=useAuth()
const syncError=useState('account-sync-error',()=> '')
const syncStatus=useState<string>('account-sync-status',()=> 'idle')
const name=ref(''),currentPassword=ref(''),password=ref(''),message=ref('')
const settingsOpen=ref(false),changePassword=ref(false),busy=ref(false),signingOut=ref(false),failed=ref(false)
const initials=computed(()=>user.value?.name.trim().split(/\s+/).slice(0,2).map(part=>part[0]).join('').toLocaleUpperCase()||'F')
const roleLabel=computed(()=>user.value?.role==='ADMIN'?'Ադմինիստրատոր':user.value?.role==='EDITOR'?'Խմբագիր':'COGNITIO-ի անդամ')
const syncing=computed(()=>['loading','saving'].includes(syncStatus.value))
const storageLabel=computed(()=>syncError.value?'Համաժամացումը չի ավարտվել':syncStatus.value==='loading'?'Բեռնում ենք քո նյութերը…':syncStatus.value==='saving'?'Պահպանում ենք փոփոխությունները…':syncStatus.value==='saved'?'Բոլոր փոփոխությունները պահպանված են':'Քո հավաքածուն կապված է այս հաշվին')
onMounted(async()=>{try{await refresh();name.value=user.value?.name||''}catch{failed.value=true;message.value='Հաշվի ծառայությունն անհասանելի է։ Փորձիր կրկին։'}})
function toggleSettings(){settingsOpen.value=!settingsOpen.value;message.value='';if(settingsOpen.value)name.value=user.value?.name||'';else{password.value='';currentPassword.value='';changePassword.value=false}}
async function save(){
 if(busy.value)return
 busy.value=true;message.value='';failed.value=false
 try{
  const result=await $fetch<{user:typeof user.value;reauthenticate:boolean}>('/api/account/profile',{method:'PUT',body:{name:name.value.trim(),...(changePassword.value?{password:password.value,currentPassword:currentPassword.value}:{})}})
  user.value=result.user;password.value='';currentPassword.value='';changePassword.value=false;message.value='Փոփոխությունները պահպանված են։'
  if(result.reauthenticate){user.value=null;window.dispatchEvent(new Event('factum-auth-changed'));await navigateTo('/login')}
 }catch(e:any){failed.value=true;message.value=e.data?.statusMessage||'Չհաջողվեց պահպանել։ Փորձիր կրկին։'}finally{busy.value=false}
}
async function signOut(){signingOut.value=true;try{await logout();await navigateTo('/login')}catch{failed.value=true;message.value='Չհաջողվեց դուրս գալ։ Փորձիր կրկին։'}finally{signingOut.value=false}}
</script>

<template>
 <section class="account-panel" aria-label="Իմ հաշիվը">
  <template v-if="user">
   <div class="account-main">
    <div class="account-identity">
     <div class="account-avatar" aria-hidden="true">{{initials}}<span><Check :size="12" /></span></div>
     <div class="account-person"><span class="account-eyebrow">ՔՈ ԱՆՁՆԱԿԱՆ ՏԱՐԱԾՔԸ</span><h1>{{user.name}}</h1><p><Mail :size="14" aria-hidden="true" />{{user.email}}</p><span class="account-role"><ShieldCheck :size="12" aria-hidden="true" />{{roleLabel}}</span></div>
    </div>
    <div class="account-actions">
     <NuxtLink v-if="user.role!=='USER'" class="account-admin" to="/admin">Կառավարման վահանակ <ArrowUpRight :size="15" /></NuxtLink>
     <button class="account-settings-button" :aria-expanded="settingsOpen" aria-controls="account-settings" @click="toggleSettings"><Settings2 :size="16" />Հաշվի կարգավորումներ<ChevronDown :size="14" :class="{'is-open':settingsOpen}" /></button>
     <button class="account-logout" :disabled="signingOut" @click="signOut"><LoaderCircle v-if="signingOut" :size="15" class="account-spin" /><LogOut v-else :size="15" />Դուրս գալ</button>
    </div>
   </div>
   <div class="account-storage" :class="{'has-error':syncError}" role="status"><LoaderCircle v-if="syncing" :size="17" class="account-spin" /><Cloud v-else :size="17" /><div><strong>{{storageLabel}}</strong><p>{{syncError||'Նույն հաշվով մուտք գործիր ցանկացած սարքից և շարունակիր այնտեղից, որտեղ կանգ ես առել։'}}</p></div><span v-if="!syncError&&!syncing" class="account-live-dot" aria-hidden="true"></span></div>
   <section v-if="settingsOpen" id="account-settings" class="account-settings">
    <div class="settings-heading"><div><h2>Հաշվի կարգավորումներ</h2><p>Թարմացրու անունդ կամ փոխիր գաղտնաբառդ։</p></div><button type="button" aria-label="Փակել կարգավորումները" class="settings-close" @click="toggleSettings"><X :size="18" /></button></div>
    <form @submit.prevent="save">
     <div class="account-fields"><label for="account-name"><span><UserRound :size="14" />Քո անունը</span><input id="account-name" v-model="name" required minlength="2" maxlength="100" autocomplete="name" :disabled="busy"></label><label for="account-email"><span><Mail :size="14" />Էլեկտրոնային հասցե</span><input id="account-email" :value="user.email" type="email" disabled><small>Այս հասցեն օգտագործվում է մուտք գործելու համար։</small></label></div>
     <button type="button" class="account-password-toggle" :aria-expanded="changePassword" aria-controls="account-password-fields" @click="changePassword=!changePassword;password='';currentPassword=''"><KeyRound :size="15" />Փոխել գաղտնաբառը<ChevronDown :size="14" :class="{'is-open':changePassword}" /></button>
     <div v-if="changePassword" id="account-password-fields" class="account-fields password-fields"><label for="account-current-password"><span>Ընթացիկ գաղտնաբառ</span><input id="account-current-password" v-model="currentPassword" type="password" required autocomplete="current-password" :disabled="busy"></label><label for="account-new-password"><span>Նոր գաղտնաբառ</span><input id="account-new-password" v-model="password" type="password" required minlength="12" maxlength="128" autocomplete="new-password" :disabled="busy"><small>Առնվազն 12 նիշ։ Փոխելուց հետո նորից մուտք կգործես։</small></label></div>
     <div class="account-form-actions"><button type="submit" class="btn account-save" :disabled="busy"><LoaderCircle v-if="busy" :size="16" class="account-spin" /><Check v-else :size="16" />{{busy?'Պահպանվում է…':'Պահպանել փոփոխությունները'}}</button><button type="button" class="account-cancel" :disabled="busy" @click="toggleSettings">Չեղարկել</button></div>
    </form>
   </section>
  </template>
  <div v-else class="account-unavailable"><UserRound :size="28" /><NuxtLink to="/login">Մուտք գործել կամ գրանցվել <ArrowUpRight :size="16" /></NuxtLink><p>Քո հավաքածուն հասանելի է քո անձնական հաշվով։</p></div>
  <p v-if="message" class="account-message" :class="{'has-error':failed}" :role="failed?'alert':'status'"><Check v-if="!failed" :size="16" />{{message}}</p>
 </section>
</template>

<style scoped>
.account-panel{position:relative;margin-bottom:42px;border:1px solid #d9bd822b;border-radius:24px;background:radial-gradient(ellipse at 5% 0%,#c9a86d13,transparent 55%),linear-gradient(125deg,#151c2b,#101725);overflow:hidden;color:#edf0f6}.account-panel::before{content:'';position:absolute;top:0;left:32px;right:32px;height:1px;background:linear-gradient(90deg,transparent,#d9bd8270,transparent)}.account-main{display:flex;justify-content:space-between;align-items:center;gap:28px;padding:34px}.account-identity{display:flex;align-items:center;gap:24px;min-width:0}.account-avatar{position:relative;display:grid;place-items:center;flex-shrink:0;width:90px;height:90px;border-radius:26px;border:1px solid #d8bb8055;background:linear-gradient(140deg,#d7b97627,#d7b97608);box-shadow:inset 0 0 25px #d7b97608;color:#e8cd95;font-size:29px;font-weight:700}.account-avatar>span{position:absolute;right:-4px;bottom:-4px;display:grid;place-items:center;width:25px;height:25px;border:4px solid #151c2b;border-radius:50%;background:#9fc8af;color:#14251c}.account-person{min-width:0}.account-eyebrow{font-size:9px;letter-spacing:1.5px;color:#c8ab78}.account-person h1{font-size:clamp(22px,3vw,32px);line-height:1.5;font-weight:750;margin:7px 0;overflow-wrap:anywhere}.account-person>p{display:flex;gap:7px;align-items:center;font-size:12px;color:#a2aec1;overflow-wrap:anywhere}.account-person>p svg{flex-shrink:0}.account-role{display:inline-flex;align-items:center;gap:5px;margin-top:12px;color:#cab58e;font-size:10px}.account-actions{display:flex;flex-direction:column;align-items:flex-end;gap:15px;flex-shrink:0}.account-actions a,.account-actions button{display:inline-flex;align-items:center;justify-content:center;gap:8px;font-size:11px;line-height:1.6}.account-admin{color:#e3c68e}.account-settings-button{padding:11px 14px;border:1px solid #9aaec22d;border-radius:10px;background:#ffffff04;color:#dae1ec}.account-settings-button:hover{border-color:#d7b97670;background:#d7b97609}.account-logout{color:#8896ac}.account-logout:hover{color:#f2a8a8}.account-storage{display:flex;align-items:center;gap:12px;padding:19px 34px;background:#080f1c45;border-top:1px solid #9aaec218;color:#9abcae}.account-storage>svg{flex-shrink:0}.account-storage strong{display:block;font-weight:500;font-size:11px}.account-storage p{color:#8d9ab0;font-size:10px;line-height:1.9;margin-top:4px}.account-live-dot{width:6px;height:6px;flex-shrink:0;border-radius:50%;margin-left:auto;background:#9ac4ab;box-shadow:0 0 0 4px #9ac4ab0c}.account-settings{border-top:1px solid #9aaec218;padding:28px 34px;background:#080f1c33}.settings-heading{display:flex;align-items:flex-start;justify-content:space-between;gap:16px;margin-bottom:25px}.settings-heading h2{font-weight:650;font-size:16px}.settings-heading p{font-size:11px;line-height:1.9;color:#8e9db2;margin-top:6px}.settings-close{padding:6px;color:#9ba9bb;border-radius:8px}.settings-close:hover{background:#ffffff0a}.account-fields{display:grid;grid-template-columns:1fr 1fr;gap:22px}.account-fields label{display:flex;flex-direction:column;gap:9px;min-width:0}.account-fields label>span{display:flex;align-items:center;gap:7px;font-size:11px;color:#c3ccda}.account-fields input{width:100%;min-width:0;border:1px solid #99abc52e;background:#080f1c99;color:#eef1f7;border-radius:10px;padding:12px 14px;font-size:13px;outline:none}.account-fields input:focus{border-color:#d4b67c;box-shadow:0 0 0 3px #d4b67c0c}.account-fields input:disabled{color:#8290a4;background:#ffffff02}.account-fields small{font-size:10px;line-height:1.8;color:#8493a9}.account-password-toggle{display:flex;align-items:center;gap:8px;color:#c7b38d;font-size:11px;margin-top:24px}.account-password-toggle svg:last-child{margin-left:8px}.password-fields{margin-top:20px}.account-form-actions{display:flex;align-items:center;gap:20px;margin-top:28px}.account-save{display:inline-flex;justify-content:center;align-items:center;gap:8px;font-size:11px;padding:12px 17px}.account-cancel{font-size:11px;color:#9ca9bb}.account-message{display:flex;align-items:center;gap:8px;padding:16px 34px;border-top:1px solid #9aaec218;color:#a5d1b7;font-size:12px;line-height:1.9}.has-error{color:#eeb1a6}.account-unavailable{display:flex;flex-direction:column;align-items:center;gap:14px;text-align:center;padding:35px}.account-unavailable>a{display:flex;align-items:center;gap:8px;color:#dfc38f}.account-unavailable p{color:#9ba9bb;font-size:12px}.is-open{transform:rotate(180deg)}button:disabled{opacity:.55;cursor:wait}button:focus-visible,a:focus-visible{outline:2px solid #d4b67c;outline-offset:4px}.account-spin{animation:account-spin 1s linear infinite}@keyframes account-spin{to{transform:rotate(360deg)}}
@media(max-width:700px){.account-main{align-items:stretch;flex-direction:column;padding:25px;gap:25px}.account-actions{flex-direction:row;align-items:center;justify-content:flex-start;flex-wrap:wrap;gap:15px}.account-admin{width:100%;justify-content:flex-start!important}.account-logout{margin-left:auto}.account-avatar{width:70px;height:70px;border-radius:21px;font-size:24px}.account-identity{gap:18px}.account-storage{padding:18px 25px}.account-settings{padding:25px}.account-fields{grid-template-columns:1fr;gap:18px}.account-panel{margin-bottom:30px}.account-message{padding:16px 25px}}@media(max-width:400px){.account-main,.account-settings{padding:20px}.account-identity{gap:14px}.account-avatar{width:58px;height:58px;border-radius:18px;font-size:20px}.account-person>p{font-size:10px}.account-settings-button{padding:10px;font-size:10px!important}.account-form-actions{align-items:stretch;flex-direction:column;gap:15px}.account-storage{padding:16px 20px}}
:global(html.factum-light .account-panel){background:linear-gradient(125deg,#fffaf0,#fff);color:#25334a;border-color:#b08b4740}:global(html.factum-light .account-panel input){background:#fff;color:#25334a}:global(html.factum-light .account-panel input:disabled){color:#778297}:global(html.factum-light .account-settings-button){color:#47566a}:global(html.factum-light .account-person>p),:global(html.factum-light .account-fields label>span){color:#596779}:global(html.factum-light .account-storage),:global(html.factum-light .account-settings){background:#c4b58c08}
@media(prefers-reduced-motion:reduce){.account-spin{animation:none}}
</style>
